#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
echo 'foo123 bar456' | grep -E '(foo|bar)[0-9]+'
echo 'a+b*c?' | grep -F 'a+b*c?'
echo 'word wordly subword' | grep -w word
printf '%b\n' 'exact whole line\npartial line' | grep -x 'exact whole line'
printf '%b\n' 'error message\nwarning message\ninfo message' | grep -E 'error|warning'
{
    __ps_tmp0="$(mktemp)"
    printf '%b\n' 'error\nwarning' >$__ps_tmp0
    printf '%b\n' 'error\nwarning' | grep -f $__ps_tmp0
    rm -f $__ps_tmp0
}
echo 'file123.txt backup456.bak' | grep -E '([a-z]+)([0-9]+)\.([a-z]+)'
matched="$(printf '%s\n' test | grep -c '.*')"
printf '%s\n' "  grep_exit: $?"
printf '%s\n' "  match_count: $matched"
